// ===================== GLOBAL SETTINGS (edit here) =====================
const CFG = {
  baseDir: '/home/node/.n8n-files/video-jobs', // must exist/writable inside the n8n container
  textModel: 'gemini-3.8-flash',
  textModelFallback: 'gemini-3.5-flash',
  imageModel: 'gemini-3.1-flash-image-preview',
  qualityProfile: 'quality',   // 'quality' = Veo 3.1 -> Fast -> Lite -> still-image ; 'economy' = Fast -> Lite -> still-image
  resolution: '720p',          // '720p' | '1080p' | '4k'  (1080p/4k force 8 s clips)
  fps: 24,
  maxScenes: 12,
  maxDurationSec: 120,
  maxFailedScenes: 1,          // abort the job if more scenes than this cannot be rendered
  clarifyRoundsMax: 2,         // max "please tell me more" emails
  revisionRoundsMax: 2,        // max human "needs changes" loops
  autoFixRoundsMax: 1,         // max automatic QA-driven re-renders
  qaPassScore: 7,              // 0-10
  enableResearch: true,        // Gemini + Google Search grounding
  burnCaptions: true,
  scenePaceSec: 8,             // pause before each Veo submit (rate-limit friendliness)
  pollIntervalSec: 15,
  maxPollMinutes: 12,
  backoffBaseSec: 15,
  backoffMaxSec: 60,
  maxSubmitRetriesPerTier: 6,
  maxPromptSoftenings: 1,
  cleanupAfter: true,
  adminEmail: '',              // optional: gets failure alerts; defaults to requester
  driveParentFolderId: 'root'  // Google Drive folder ID where job folders are created
};
// ======================================================================
const T = {
  std:   { model: 'veo-3.1-generate-preview',       supportsRefs: true,  maxRes: '4k' },
  fast:  { model: 'veo-3.1-fast-generate-preview',  supportsRefs: true,  maxRes: '4k' },
  lite:  { model: 'veo-3.1-lite-generate-preview',  supportsRefs: false, maxRes: '1080p' },
  still: { model: 'still' }
};
const tiers = CFG.qualityProfile === 'economy' ? [T.fast, T.lite, T.still] : [T.std, T.fast, T.lite, T.still];

const item = $input.first();
const f = item.json || {};
const pick = (prefix) => {
  const k = Object.keys(f).find((x) => x.toLowerCase().startsWith(prefix));
  return k ? f[k] : '';
};
const topic = String(pick('topic') || '').trim();
const instructions = String(pick('instructions') || '').trim();
let typeHint = String(pick('video type') || '').trim();
if (/^not sure/i.test(typeHint)) typeHint = '';
const dur = Number(pick('duration'));
const email = String(pick('your email') || pick('email') || '').trim();
if (!topic) throw new Error('Topic is required.');
if (!email) throw new Error('Email is required (needed for review/approval).');

const jobId = 'job_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const urls = Array.from(new Set(((topic + ' ' + instructions).match(/https?:\/\/[^\s)>"']+/g)) || []));

const job = {
  jobId,
  jobDir: CFG.baseDir + '/' + jobId,
  createdAt: new Date().toISOString(),
  requesterEmail: email,
  adminEmail: CFG.adminEmail || email,
  topic,
  instructions,
  videoTypeHint: typeHint,
  durationHintSec: Number.isFinite(dur) && dur > 0 ? dur : null,
  urls,
  answers: [],
  clarifyRound: 0,
  revisionRound: 0,
  autoFixRound: 0,
  revisionNotes: [],
  clips: {},
  cfg: CFG,
  tiers
};
return [{ json: job, binary: item.binary || {} }];

const fs = require('fs');
const zlib = require('zlib');
const helpers = this.helpers;
const src = $input.first();
const job = { ...src.json };
const bin = src.binary || {};
const dir = job.jobDir;
['in', 'clips', 'work', 'out'].forEach((d) => fs.mkdirSync(dir + '/' + d, { recursive: true }));

const MIME = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', pdf: 'application/pdf',
  mp4: 'video/mp4', mov: 'video/quicktime', webm: 'video/webm', mp3: 'audio/mpeg', wav: 'audio/wav', m4a: 'audio/mp4' };
const IMG = ['png', 'jpg', 'jpeg', 'webp'];
const MEDIA = ['mp4', 'mov', 'webm', 'mp3', 'wav', 'm4a'];
const TEXT = ['txt', 'md', 'csv', 'json', 'html', 'htm', 'xml', 'srt', 'vtt'];
const INLINE_EACH = 8 * 1024 * 1024, INLINE_TOTAL = 14 * 1024 * 1024, TEXT_TOTAL = 150000;

function unzipEntries(buf, wanted) {
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) return [];
  const count = buf.readUInt16LE(eocd + 10);
  let off = buf.readUInt32LE(eocd + 16);
  const out = [];
  for (let n = 0; n < count; n++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) break;
    const method = buf.readUInt16LE(off + 10);
    const csize = buf.readUInt32LE(off + 20);
    const nlen = buf.readUInt16LE(off + 28), elen = buf.readUInt16LE(off + 30), clen = buf.readUInt16LE(off + 32);
    const lho = buf.readUInt32LE(off + 42);
    const name = buf.toString('utf8', off + 46, off + 46 + nlen);
    if (wanted(name)) {
      const start = lho + 30 + buf.readUInt16LE(lho + 26) + buf.readUInt16LE(lho + 28);
      const raw = buf.subarray(start, start + csize);
      out.push({ name, data: method === 0 ? raw : zlib.inflateRawSync(raw) });
    }
    off += 46 + nlen + elen + clen;
  }
  return out;
}
const decode = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
function docxText(buf) {
  const e = unzipEntries(buf, (n) => n === 'word/document.xml')[0];
  if (!e) return '';
  return decode(e.data.toString('utf8').replace(/<w:tab\/>/g, '\t').replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, ''));
}
function pptxText(buf) {
  const es = unzipEntries(buf, (n) => /^ppt\/slides\/slide\d+\.xml$/.test(n))
    .sort((a, b) => parseInt(a.name.match(/(\d+)\.xml/)[1]) - parseInt(b.name.match(/(\d+)\.xml/)[1]));
  return es.map((e, i) => 'Slide ' + (i + 1) + ':\n' + decode(e.data.toString('utf8').replace(/<\/a:p>/g, '\n').replace(/<[^>]+>/g, ''))).join('\n\n');
}

const files = [], inlineParts = [], warnings = [];
let inlineBytes = 0, textChars = 0;
const used = new Set();
const keys = Object.keys(bin);
for (let i = 0; i < keys.length; i++) {
  const k = keys[i], b = bin[k];
  const orig = String(b.fileName || k);
  const ext = String(b.fileExtension || orig.split('.').pop() || '').toLowerCase();
  let safe = orig.replace(/[^A-Za-z0-9._-]+/g, '_') || ('file_' + i);
  if (!/\.[A-Za-z0-9]+$/.test(safe)) safe += '.' + ext;
  if (used.has(safe)) safe = (i + 1) + '_' + safe;
  used.add(safe);
  const buf = await helpers.getBinaryDataBuffer(0, k);
  const path = dir + '/in/' + safe;
  fs.writeFileSync(path, buf);
  const rec = { name: safe, originalName: orig, path, ext, bytes: buf.length, kind: 'other' };
  try {
    if (IMG.includes(ext)) rec.kind = 'image';
    else if (ext === 'pdf') rec.kind = 'doc';
    else if (MEDIA.includes(ext)) rec.kind = 'media';
    else if (ext === 'docx') { rec.kind = 'doc'; rec.text = docxText(buf); }
    else if (ext === 'pptx') { rec.kind = 'doc'; rec.text = pptxText(buf); }
    else if (TEXT.includes(ext)) { rec.kind = 'doc'; rec.text = buf.toString('utf8'); }
    else warnings.push('Unsupported file type ignored for analysis: ' + safe);
  } catch (e) { warnings.push('Could not read ' + safe + ': ' + e.message); }
  if (rec.text) {
    rec.text = rec.text.slice(0, 60000);
    if (textChars + rec.text.length > TEXT_TOTAL) { rec.text = rec.text.slice(0, Math.max(0, TEXT_TOTAL - textChars)); warnings.push('Text truncated for ' + safe); }
    textChars += rec.text.length;
  }
  if (MIME[ext] && ['image', 'media'].includes(rec.kind) || ext === 'pdf') {
    if (buf.length <= INLINE_EACH && inlineBytes + buf.length <= INLINE_TOTAL) {
      inlineParts.push({ text: '[Attached file: ' + safe + ']' });
      inlineParts.push({ inline_data: { mime_type: MIME[ext], data: buf.toString('base64') } });
      inlineBytes += buf.length;
      rec.inlined = true;
    } else warnings.push(safe + ' is too large to analyse inline (kept on disk; images can still be used as Veo references).');
  }
  files.push(rec);
}
job.assets = { files, warnings };
fs.writeFileSync(dir + '/job.json', JSON.stringify({ ...job }, null, 2));
return [{ json: { ...job, inlineParts } }];

const j = $input.first().json;
const files = (j.assets && j.assets.files) || [];
const docText = files.filter((f) => f.text).map((f) => '### FILE: ' + f.name + '\n' + f.text).join('\n\n').slice(0, 120000);
const answers = (j.answers || []).map((a, i) => 'Clarification round ' + (i + 1) + ' answers: ' + JSON.stringify(a)).join('\n');
const known = j.assetSummaries && j.assetSummaries.length ? 'Previously analysed attachments: ' + JSON.stringify(j.assetSummaries) : '';
const prompt = `You are the INTAKE ANALYST of an automated AI video studio (clips are made with Google Veo 3.1: 4/6/8-second clips with native audio, stitched together).
Decide whether the request contains enough information to start production, and normalise it into a spec.

USER REQUEST
Topic: ${j.topic}
Instructions: ${j.instructions || '(none)'}
Video type hint: ${j.videoTypeHint || '(none)'}
Duration hint (seconds): ${j.durationHintSec || '(none)'}
URLs mentioned: ${(j.urls || []).join(', ') || '(none)'}
${answers}
${known}
${(j.assets && j.assets.warnings || []).join('\n')}

ATTACHED DOCUMENT TEXT
${docText || '(none)'}

RULES
- A request is COMPLETE when you can confidently determine: purpose/video type, platform or format (-> aspect ratio), target duration, language, and tone/style. Infer when the wording makes it obvious (e.g. "reel" => 9:16, "YouTube explainer" => 16:9); otherwise list it as missing.
- Duration and format/platform MUST be known or explicitly inferable; if not, mark incomplete and ask.
- Ask at most 4 short, concrete questions. Never ask for something already answered or visible in the attachments.
- Maximum allowed duration is ${j.cfg.maxDurationSec} seconds.
- For each attachment, describe what it contains and the best use: reference (keep subject/character/product look), first_frame, logo, background_info, or ignore.

Return ONLY JSON with exactly this shape:
{"complete":boolean,
 "missing":[{"field":"duration|platform|language|style|audience|goal|other","question":"..."}],
 "spec":{"title":"","videoType":"reel|short|tiktok|ad|explainer|cinematic|story|other","platform":"","aspectRatio":"9:16|16:9","durationSec":number,"language":"","tone":"","style":"","audience":"","goal":"","cta":"","captions":boolean,"mustInclude":[],"avoid":[]},
 "assetSummaries":[{"name":"","description":"","bestUse":""}],
 "assumptions":[""]}`;
const parts = [{ text: prompt }].concat(j.inlineParts || []);
const reqBody = { contents: [{ role: 'user', parts }], generationConfig: { responseMimeType: 'application/json', temperature: 0.2 } };
return [{ json: { ...j, model: j.cfg.textModel, reqBody } }];

const req = $('Build Intake Request').first().json;
const r = $input.first().json || {};
const job = { ...req };
delete job.reqBody; delete job.inlineParts; delete job.model;

function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(t); } catch (e) {
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a >= 0 && b > a) return JSON.parse(t.slice(a, b + 1));
    throw e;
  }
}
let parsed = null, failure = '';
try {
  if (r.error || !r.candidates) throw new Error(typeof r.error === 'string' ? r.error : JSON.stringify(r.error || r).slice(0, 300));
  const text = (r.candidates[0].content.parts || []).map((p) => p.text || '').join('');
  parsed = parseJson(text);
} catch (e) { failure = e.message; }

if (!parsed) {
  parsed = { complete: false, missing: [{ field: 'other', question: 'Please describe the video type/platform, target duration and language.' }], spec: {}, assetSummaries: [], assumptions: ['Intake analysis failed (' + failure + ')'] };
}
const spec = { ...(job.spec || {}), ...(parsed.spec || {}) };
if (!job.assetSummaries || !job.assetSummaries.length) job.assetSummaries = parsed.assetSummaries || [];
else if (parsed.assetSummaries && parsed.assetSummaries.length) job.assetSummaries = parsed.assetSummaries;

const typ = String(spec.videoType || job.videoTypeHint || '').toLowerCase();
const vertical = /reel|short|tiktok|story|vertical|ad/.test(typ) || /instagram|tiktok|shorts/i.test(String(spec.platform || ''));
let complete = !!parsed.complete && Number(spec.durationSec) > 0 && !!spec.aspectRatio;
const proceed = complete || (job.clarifyRound >= job.cfg.clarifyRoundsMax);

const assumptions = parsed.assumptions || [];
if (proceed) {
  if (!(Number(spec.durationSec) > 0)) {
    spec.durationSec = job.durationHintSec || (/explainer/.test(typ) ? 60 : /cinematic/.test(typ) ? 24 : 30);
    assumptions.push('Duration not specified; assumed ' + spec.durationSec + 's.');
  }
  if (!spec.aspectRatio) { spec.aspectRatio = vertical ? '9:16' : '16:9'; assumptions.push('Aspect ratio assumed ' + spec.aspectRatio + '.'); }
}
if (spec.durationSec) spec.durationSec = Math.max(4, Math.min(job.cfg.maxDurationSec, Math.round(Number(spec.durationSec))));
if (spec.aspectRatio !== '9:16' && spec.aspectRatio !== '16:9') spec.aspectRatio = vertical ? '9:16' : '16:9';
if (!spec.title) spec.title = job.topic.slice(0, 80);
if (spec.captions === undefined) spec.captions = job.cfg.burnCaptions;

job.spec = spec;
job.missing = proceed ? [] : (parsed.missing && parsed.missing.length ? parsed.missing : [{ field: 'other', question: 'Please add any missing details (duration, platform, language, style).' }]);
job.assumptions = assumptions;
job.proceed = proceed;
return [{ json: job }];

const prev = $('Parse Intake').first().json;
const resp = $input.first().json || {};
const d = resp.data;
if (!d || typeof d !== 'object') {
  throw new Error('No reply to the clarification email within the wait limit - job ' + prev.jobId + ' cancelled.');
}
const job = { ...prev };
delete job.missing; delete job.proceed;
job.answers = [...(prev.answers || []), d];
job.clarifyRound = (prev.clarifyRound || 0) + 1;
const val = (p) => { const k = Object.keys(d).find((x) => x.toLowerCase().startsWith(p)); return k ? String(d[k] || '').trim() : ''; };
const t = val('video type'), dur = Number(val('duration'));
if (t && !/^not sure|other/i.test(t)) job.videoTypeHint = t;
if (Number.isFinite(dur) && dur > 0) job.durationHintSec = dur;
return [{ json: job }];

const j = $input.first().json;
const tools = [{ google_search: {} }];
if ((j.urls || []).length) tools.push({ url_context: {} });
const docs = ((j.assets && j.assets.files) || []).filter((f) => f.text).map((f) => f.name + ': ' + f.text.slice(0, 1500)).join('\n');
const prompt = `You are a research assistant for a video production team. Use Google Search${(j.urls || []).length ? ' and the provided URLs' : ''} to collect accurate, current information for the video below.

TOPIC: ${j.topic}
INSTRUCTIONS: ${j.instructions || '(none)'}
VIDEO SPEC: ${JSON.stringify(j.spec)}
URLS: ${(j.urls || []).join(', ') || '(none)'}
USER DOCUMENT EXCERPTS (treat as primary source of truth): ${docs || '(none)'}

Reply in plain text with these sections: KEY FACTS (with numbers/dates), WHAT THE AUDIENCE CARES ABOUT, COMMON MISCONCEPTIONS, TERMS/NAMES TO GET RIGHT, VISUAL REFERENCES AND SETTINGS, TRUSTWORTHY SOURCES.
If the topic is purely fictional, creative or brand-internal and needs no external facts, reply exactly: NO_RESEARCH_NEEDED
Maximum 600 words.`;
const reqBody = { contents: [{ role: 'user', parts: [{ text: prompt }] }], tools, generationConfig: { temperature: 0.3 } };
return [{ json: { ...j, model: j.cfg.textModel, reqBody } }];

const req = $('Build Research Request').first().json;
const r = $input.first().json || {};
const job = { ...req };
delete job.reqBody; delete job.model;
let text = '', sources = [];
try {
  const c = r.candidates && r.candidates[0];
  text = ((c && c.content && c.content.parts) || []).map((p) => p.text || '').join('').trim();
  const chunks = (c && c.groundingMetadata && c.groundingMetadata.groundingChunks) || [];
  sources = chunks.filter((x) => x.web).map((x) => ({ title: x.web.title, url: x.web.uri })).slice(0, 12);
} catch (e) { /* research is best-effort */ }
if (/^NO_RESEARCH_NEEDED/i.test(text)) text = '';
job.research = { text, sources, ok: !!text };
return [{ json: job }];

const j = $input.first().json;
const cfg = j.cfg, spec = j.spec;
const hiRes = cfg.resolution !== '720p';
const files = (j.assets && j.assets.files) || [];
const sum = (n) => (j.assetSummaries || []).find((a) => a.name === n) || {};
const images = files.filter((f) => f.kind === 'image' && !f.generated).map((f) => '- ' + f.name + ': ' + (sum(f.name).description || 'user image') + ' (suggested use: ' + (sum(f.name).bestUse || 'reference') + ')').join('\n');
const docs = files.filter((f) => f.text).map((f) => '### ' + f.name + '\n' + f.text.slice(0, 20000)).join('\n\n').slice(0, 60000);
const answers = (j.answers || []).map((a) => JSON.stringify(a)).join('\n');
const revising = j.storyboard && (j.revisionNotes || []).length;
const maxTotal = Math.min(spec.durationSec + 4, cfg.maxScenes * 8);

const prompt = `You are the CREATIVE DIRECTOR + STORYBOARD PLANNER of an automated AI video studio. Clips are generated with Google Veo 3.1 (text/image-to-video with NATIVE AUDIO: speech, sound effects, ambience, music). Each clip is exactly ${hiRes ? '8' : '4, 6 or 8'} seconds. Clips are stitched together afterwards.

BRIEF
Title: ${spec.title}
Topic: ${j.topic}
Instructions: ${j.instructions || '(none)'}
Spec: ${JSON.stringify(spec)}
User clarification answers: ${answers || '(none)'}
Assumptions made: ${(j.assumptions || []).join(' | ') || '(none)'}

RESEARCH NOTES (verify claims against these, do not invent facts)
${(j.research && j.research.text) || '(none)'}

USER IMAGES AVAILABLE (use these exact file names in imageUse.files)
${images || '(none)'}

USER DOCUMENT CONTENT
${docs || '(none)'}

HARD CONSTRAINTS
- Aspect ratio ${spec.aspectRatio}. Target total duration ${spec.durationSec}s (sum of scene durations must be between ${Math.max(4, spec.durationSec - 4)} and ${maxTotal}). Max ${cfg.maxScenes} scenes.
- ${hiRes ? 'Every scene durationSec MUST be 8.' : 'Every scene durationSec must be 4, 6 or 8.'}
- Scenes using imageUse.mode "reference" (max 3 images) are always generated at 8s. mode "first_frame" uses exactly 1 image as the opening frame. Otherwise mode "none".
- If the user supplied no suitable images but visual consistency of a character/product across scenes matters, add up to 3 referenceImagePrompts (ids R1..R3) and use those ids in imageUse.files. Otherwise leave referenceImagePrompts empty.
- Veo prompt craft: each visualPrompt is self-contained and includes: subject (repeat the FULL character/product description every scene for consistency), action, setting, visual style, camera position/motion, composition, lens/focus, lighting/ambience.
- Audio is generated by Veo: write spoken lines in quotes with who speaks and a voice description (reuse identical voice descriptions across scenes), add sound effects and ambience, and music direction. Keep dialogue to about 2.5 words per second of scene length. Language of speech: ${spec.language || 'English'}.
- Do NOT request on-screen text, subtitles, captions, watermarks or logos inside the Veo prompt (captions are added in post). Put wanted on-screen text in onScreenText instead.
- ${spec.aspectRatio === '9:16' ? 'Vertical short-form: strong hook in the first 3 seconds, fast pacing, one idea per scene, clear CTA at the end.' : 'Landscape: clear narrative arc (hook, development, payoff), establishing and detail shots mixed.'}
- safeVisualPrompt = a softened rewrite of visualPrompt (no real people/celebrities, brands, violence, minors, medical or political claims) that conveys the same idea; used automatically if Veo's safety filter blocks the original.
- Must include: ${(spec.mustInclude || []).join('; ') || '-'}. Must avoid: ${(spec.avoid || []).join('; ') || '-'}.
${revising ? `
REVISION MODE
Existing storyboard (JSON): ${JSON.stringify(j.storyboard)}
Feedback to apply: ${(j.revisionNotes || []).join('\n')}
Change ONLY the scenes affected by the feedback (and the style bible if required). Every unaffected scene must be returned with its visualPrompt, safeVisualPrompt, durationSec and imageUse EXACTLY identical to the existing storyboard so already-rendered clips are reused. You may add, remove or reorder scenes only if the feedback requires it.` : ''}

Return ONLY JSON with exactly this shape:
{"title":"","logline":"",
 "styleBible":{"visualStyle":"","palette":"","cameraLanguage":"","lighting":"","characters":[{"id":"C1","description":""}],"locations":[""],"audioStyle":"","voice":""},
 "referenceImagePrompts":[{"id":"R1","purpose":"character|product|style","prompt":""}],
 "scenes":[{"index":1,"durationSec":8,"purpose":"hook","visualPrompt":"","safeVisualPrompt":"","dialogue":"","onScreenText":"","transition":"cut","imageUse":{"mode":"none","files":[]}}],
 "caption":"social caption with hashtags","thumbnailIdea":"","musicDirection":""}`;
const model = j.useFallback ? cfg.textModelFallback : cfg.textModel;
const reqBody = { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.8, maxOutputTokens: 24000 } };
return [{ json: { ...j, model, reqBody } }];

const fs = require('fs');
const req = $('Build Planner Request').first().json;
const r = $input.first().json || {};
const job = { ...req };
delete job.reqBody; delete job.model;
const cfg = job.cfg, spec = job.spec;
const hiRes = cfg.resolution !== '720p';

function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(t); } catch (e) {
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a >= 0 && b > a) return JSON.parse(t.slice(a, b + 1));
    throw e;
  }
}
const fnv = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };

let sb = null, failure = '';
try {
  if (r.error || !r.candidates) throw new Error(typeof r.error === 'string' ? r.error : JSON.stringify(r.error || r).slice(0, 300));
  const text = (r.candidates[0].content.parts || []).map((p) => p.text || '').join('');
  sb = parseJson(text);
  if (!sb || !Array.isArray(sb.scenes) || !sb.scenes.length) throw new Error('storyboard has no scenes');
} catch (e) { failure = e.message; sb = null; }

if (!sb) {
  if (!job.useFallback) return [{ json: { ...job, retryPlanner: true, useFallback: true } }];
  throw new Error('Storyboard planning failed on primary and fallback model: ' + failure);
}

const files = (job.assets && job.assets.files) || [];
let scenes = sb.scenes.filter((s) => s && s.visualPrompt).slice(0, cfg.maxScenes);
let total = 0;
scenes = scenes.map((s, i) => {
  let d = Math.round(Number(s.durationSec) || 8);
  d = [4, 6, 8].reduce((p, c) => (Math.abs(c - d) < Math.abs(p - d) ? c : p));
  if (hiRes) d = 8;
  const iu = s.imageUse || {};
  let mode = ['reference', 'first_frame'].includes(iu.mode) ? iu.mode : 'none';
