sh.push('ffmpeg -hide_banner -loglevel error -y -f concat -safe 0 -i "' + work + '/list.txt"' + vf + ' -af "loudnorm=I=-16:TP=-1.5:LRA=11" ' + vcodec + ' -c:a aac -b:a 192k -movflags +faststart "' + out + '/final.mp4"');
const thumbAt = Math.min(2, Math.max(0.5, t / 4)).toFixed(2);
sh.push('ffmpeg -hide_banner -loglevel error -y -ss ' + thumbAt + ' -i "' + out + '/final.mp4" -frames:v 1 -q:v 2 "' + out + '/thumbnail.jpg"');
const scale = vertical ? 'scale=480:-2' : 'scale=-2:480';
const scale2 = vertical ? 'scale=320:-2' : 'scale=-2:320';
sh.push('ffmpeg -hide_banner -loglevel error -y -i "' + out + '/final.mp4" -vf "' + scale + '" -r 24 -c:v libx264 -preset veryfast -crf 31 -c:a aac -b:a 64k -ac 1 -movflags +faststart "' + out + '/proxy.mp4"');
sh.push('if [ "$(stat -c %s "' + out + '/proxy.mp4")" -gt 12000000 ]; then ffmpeg -hide_banner -loglevel error -y -i "' + out + '/final.mp4" -vf "' + scale2 + '" -r 15 -c:v libx264 -preset veryfast -crf 36 -c:a aac -b:a 32k -ac 1 -movflags +faststart "' + out + '/proxy.mp4"; fi');
sh.push('echo "DURATION=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "' + out + '/final.mp4")"');
sh.push('echo "SIZE_FINAL=$(stat -c %s "' + out + '/final.mp4")"');
sh.push('echo "SIZE_PROXY=$(stat -c %s "' + out + '/proxy.mp4")"');
fs.writeFileSync(work + '/assemble.sh', sh.join('\n') + '\n');
return [{ json: { ...job, assembledScenes: scenes.map((s) => s.index), plannedDurationSec: t, assembleCmd: 'sh "' + work + '/assemble.sh"' } }];

const fs = require('fs');
const job = { ...$('Build Assemble Script').first().json };
const r = $input.first().json || {};
const out = job.jobDir + '/out';
const out_files = { final: out + '/final.mp4', thumbnail: out + '/thumbnail.jpg', proxy: out + '/proxy.mp4' };
for (const k of Object.keys(out_files)) {
  if (!fs.existsSync(out_files[k]) || fs.statSync(out_files[k]).size < 1000) {
    throw new Error('Assembly failed: missing ' + k + '. ffmpeg said: ' + String(r.stderr || r.stdout || '').slice(-800));
  }
}
const m = String(r.stdout || '').match(/DURATION=([\d.]+)/);
job.out = out_files;
job.finalDurationSec = m ? Math.round(parseFloat(m[1]) * 10) / 10 : job.plannedDurationSec;
job.finalBytes = fs.statSync(out_files.final).size;
delete job.assembleCmd;
fs.writeFileSync(job.jobDir + '/job.json', JSON.stringify(job, null, 2));
return [{ json: job }];

const fs = require('fs');
const j = $input.first().json;
const sb = j.storyboard, spec = j.spec;
let t = 0;
const timeline = sb.scenes.filter((s) => (j.assembledScenes || []).includes(s.index)).map((s) => {
  const row = 'Scene ' + s.index + ' [' + t + 's-' + (t + s.durationSec) + 's] purpose=' + s.purpose + ' | dialogue=' + JSON.stringify(s.dialogue) + ' | onScreenText=' + JSON.stringify(s.onScreenText) + ' | intended=' + s.visualPrompt.slice(0, 260);
  t += s.durationSec;
  return row;
}).join('\n');
const prompt = `You are a strict, experienced video QA editor. Watch the attached video (low-resolution preview) and judge it against the brief.

BRIEF: ${j.topic} | ${j.instructions || ''}
SPEC: ${JSON.stringify(spec)}
SCENE TIMELINE:
${timeline}

Check: (1) matches the brief and key message, (2) hook strength in the first 3 seconds, (3) visual continuity of characters/products/style between scenes, (4) AI artifacts (warped hands/faces, flicker, melting objects, gibberish text), (5) audio: speech clarity, sound/music fit, abrupt cuts or volume jumps, (6) pacing and duration, (7) factual claims vs research: ${((j.research && j.research.text) || 'n/a').slice(0, 1500)}
Map each issue to the scene index it belongs to (use the timeline) or null if global. severity "major" only for problems a viewer would clearly notice or that contradict the brief.

Return ONLY JSON:
{"score":0-10,"summary":"2-3 sentences","strengths":[""],"issues":[{"sceneIndex":1,"severity":"major|minor","problem":"","fix":"how to change the scene prompt"}]}`;
const buf = fs.readFileSync(j.out.proxy);
let parts;
if (buf.length > 14 * 1024 * 1024) {
  parts = [{ text: 'Reply with exactly this JSON: {"score":null,"summary":"Preview too large for automated QA.","strengths":[],"issues":[]}' }];
} else {
  parts = [{ inline_data: { mime_type: 'video/mp4', data: buf.toString('base64') } }, { text: prompt }];
}
const reqBody = { contents: [{ role: 'user', parts }], generationConfig: { responseMimeType: 'application/json', temperature: 0.2 } };
return [{ json: { ...j, model: j.cfg.textModel, reqBody } }];

const fs = require('fs');
const req = $('Build QA Request').first().json;
const r = $input.first().json || {};
const job = { ...req };
delete job.reqBody; delete job.model;
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(t); } catch (e) { const a = t.indexOf('{'), b = t.lastIndexOf('}'); if (a >= 0 && b > a) return JSON.parse(t.slice(a, b + 1)); throw e; }
}
let qa = null;
try {
  if (r.error || !r.candidates) throw new Error('QA call failed');
  qa = parseJson((r.candidates[0].content.parts || []).map((p) => p.text || '').join(''));
} catch (e) { qa = null; }
const cfg = job.cfg;
if (!qa || qa.score === null || qa.score === undefined) {
  qa = { score: null, summary: (qa && qa.summary) || 'Automated QA was unavailable; please review the preview carefully.', strengths: [], issues: [], unavailable: true };
}
qa.issues = Array.isArray(qa.issues) ? qa.issues : [];
const major = qa.issues.filter((i) => String(i.severity).toLowerCase() === 'major');
qa.passes = qa.unavailable ? true : (Number(qa.score) >= cfg.qaPassScore && major.length === 0);
const fixable = major.filter((i) => Number.isInteger(i.sceneIndex) && job.storyboard.scenes.some((s) => s.index === i.sceneIndex));
job.qa = qa;
job.needAutoFix = !qa.passes && !qa.unavailable && (job.autoFixRound || 0) < cfg.autoFixRoundsMax && fixable.length > 0;
fs.writeFileSync(job.jobDir + '/job.json', JSON.stringify(job, null, 2));
return [{ json: job }];

const j = $input.first().json;
const notes = (j.qa.issues || []).filter((i) => i.sceneIndex || String(i.severity).toLowerCase() === 'major')
  .map((i) => 'Scene ' + (i.sceneIndex || 'global') + ' (' + i.severity + '): ' + i.problem + ' -> ' + i.fix);
return [{ json: { ...j, revisionNotes: ['AUTOMATIC QA FEEDBACK (score ' + j.qa.score + '/10):\n' + notes.join('\n')], autoFixRound: (j.autoFixRound || 0) + 1, needAutoFix: false, useFallback: false } }];

const fs = require('fs');
const j = $input.first().json;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const qa = j.qa || {};
const scenes = j.storyboard.scenes.map((s) => '<li><b>Scene ' + s.index + '</b> (' + s.durationSec + 's, ' + esc(s.purpose) + ')' + (s.dialogue ? ' - "' + esc(s.dialogue) + '"' : '') + (j.clips[s.index] && j.clips[s.index].source === 'still' ? ' <i>[animated still fallback]</i>' : '') + '</li>').join('');
const issues = (qa.issues || []).map((i) => '<li>[' + esc(i.severity) + '] Scene ' + esc(i.sceneIndex || 'global') + ': ' + esc(i.problem) + '</li>').join('');
const html = '<h2>' + esc(j.storyboard.title) + '</h2><p>' + esc(j.storyboard.logline) + '</p>'
  + '<p><b>Format:</b> ' + esc(j.spec.aspectRatio) + ', ' + j.finalDurationSec + 's &nbsp; <b>Job:</b> ' + j.jobId + '</p>'
  + '<p><b>Automated QA:</b> ' + (qa.score === null || qa.score === undefined ? 'n/a' : qa.score + '/10') + ' - ' + esc(qa.summary) + '</p>'
  + (issues ? '<p>QA issues:</p><ul>' + issues + '</ul>' : '')
  + ((j.assumptions || []).length ? '<p><b>Assumptions I made:</b></p><ul>' + j.assumptions.map((a) => '<li>' + esc(a) + '</li>').join('') + '</ul>' : '')
  + ((j.renderNotes || []).length ? '<p><b>Render notes:</b></p><ul>' + j.renderNotes.map((a) => '<li>' + esc(a) + '</li>').join('') + '</ul>' : '')
  + '<p><b>Storyboard</b></p><ul>' + scenes + '</ul>'
  + '<p>The attached file is a small preview. A second email follows with the Approve / Needs-changes buttons. The full-quality video is saved to Google Drive only after you approve.</p>';
const text = j.storyboard.title + ' - ' + j.spec.aspectRatio + ', ' + j.finalDurationSec + 's\n'
  + 'Automated QA: ' + (qa.score === null || qa.score === undefined ? 'n/a' : qa.score + '/10') + ' - ' + (qa.summary || '') + '\n\n'
  + 'Please watch the preview video attached to the previous email, then choose below.\n'
  + 'Approve = save the full-quality video + thumbnail + script to Google Drive.\n'
  + 'Needs changes = tell me what to change and I will regenerate only the affected scenes.';
const buf = fs.readFileSync(j.out.proxy);
const bin = await this.helpers.prepareBinaryData(buf, 'preview.mp4', 'video/mp4');
return [{ json: { ...j, previewHtml: html, approvalText: text, previewSubject: 'Preview: ' + j.storyboard.title }, binary: { data: bin } }];

const j = { ...$('Load Preview').first().json };
delete j.previewHtml; delete j.approvalText; delete j.previewSubject;
const title = String((j.storyboard && j.storyboard.title) || j.spec.title || 'video');
j.slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || 'video';
j.folderName = new Date().toISOString().slice(0, 10) + ' - ' + title.slice(0, 80) + ' (' + j.jobId + ')';
return [{ json: j }];

const fs = require('fs');
const helpers = this.helpers;
const j = $('Restore Job (Approved)').first().json;
const folderId = $input.first().json.id;
if (!folderId) throw new Error('Drive folder was not created.');
const sb = j.storyboard;
const mk = async (buf, name, mime) => ({ json: { fileName: name, folderId, jobId: j.jobId }, binary: { data: await helpers.prepareBinaryData(buf, name, mime) } });

const md = ['# ' + sb.title, '', sb.logline, '', '**Format:** ' + j.spec.aspectRatio + ' - ' + j.finalDurationSec + 's - language: ' + (j.spec.language || 'n/a'), '',
  '## Social caption', sb.caption || '-', '', '## Music direction', sb.musicDirection || '-', '', '## Scenes', ''];
sb.scenes.forEach((s) => {
  md.push('### Scene ' + s.index + ' (' + s.durationSec + 's) - ' + (s.purpose || ''));
  if (s.dialogue) md.push('**Dialogue:** ' + s.dialogue);
  if (s.onScreenText) md.push('**On-screen text:** ' + s.onScreenText);
  md.push('**Veo prompt:** ' + s.visualPrompt, '');
});
if (j.research && j.research.sources && j.research.sources.length) {
  md.push('## Research sources', ...j.research.sources.map((x) => '- ' + (x.title || x.url) + ' - ' + x.url));
}
const manifest = {
  jobId: j.jobId, createdAt: j.createdAt, requester: j.requesterEmail, spec: j.spec, assumptions: j.assumptions,
  qa: j.qa, renderStats: j.renderStats, renderNotes: j.renderNotes, finalDurationSec: j.finalDurationSec,
  scenes: sb.scenes.map((s) => ({ index: s.index, durationSec: s.durationSec, hash: s.hash, clip: j.clips[s.index] ? { source: j.clips[s.index].source, model: j.clips[s.index].model, attempts: j.clips[s.index].attempts, errors: j.clips[s.index].errors } : null })),
  revisionRounds: j.revisionRound, autoFixRounds: j.autoFixRound
};
return [
  await mk(fs.readFileSync(j.out.final), j.slug + '.mp4', 'video/mp4'),
  await mk(fs.readFileSync(j.out.thumbnail), j.slug + '-thumbnail.jpg', 'image/jpeg'),
  await mk(Buffer.from(md.join('\n'), 'utf8'), j.slug + '-script.md', 'text/markdown'),
  await mk(Buffer.from(JSON.stringify(sb, null, 2), 'utf8'), j.slug + '-storyboard.json', 'application/json'),
  await mk(Buffer.from(JSON.stringify(manifest, null, 2), 'utf8'), j.slug + '-manifest.json', 'application/json')
];

const j = { ...$('Restore Job (Approved)').first().json };
const folderId = $('Create Drive Folder').first().json.id;
const ups = $input.all().map((i) => i.json);
const video = ups.find((u) => /\.mp4$/i.test(u.name || '')) || ups[0] || {};
j.driveFolderUrl = 'https://drive.google.com/drive/folders/' + folderId;
j.videoUrl = video.id ? 'https://drive.google.com/file/d/' + video.id + '/view' : j.driveFolderUrl;
j.deliveryMessage = 'Approved and saved.\n\n"' + j.storyboard.title + '" (' + j.spec.aspectRatio + ', ' + j.finalDurationSec + 's)\nVideo: ' + j.videoUrl + '\nFolder (video, thumbnail, script, storyboard, manifest): ' + j.driveFolderUrl + '\n\nSuggested caption:\n' + (j.storyboard.caption || '-');
const dir = j.jobDir;
j.cleanupCmd = (j.cfg.cleanupAfter && /\/video-jobs\/job_[a-z0-9]+$/.test(dir)) ? 'rm -rf "' + dir + '"' : 'echo "cleanup skipped"';
