const j = { ...$('Load Preview').first().json };
delete j.previewHtml; delete j.approvalText; delete j.previewSubject;
return [{ json: j }];

const j = { ...$('Restore Job (Rejected)').first().json };
const d = ($input.first().json || {}).data;
const get = (p) => { if (!d) return ''; const k = Object.keys(d).find((x) => x.toLowerCase().startsWith(p)); return k ? String(d[k] || '').trim() : ''; };
const decision = get('decision'), text = get('what should');
let revise = false, reason = '';
if (!d) reason = 'No reply to the feedback request within the wait limit.';
else if (!/revise/i.test(decision)) reason = 'You chose to cancel this job.';
else if (!text) reason = 'No change instructions were provided.';
else if ((j.revisionRound || 0) >= j.cfg.revisionRoundsMax) reason = 'The maximum number of revision rounds (' + j.cfg.revisionRoundsMax + ') has been reached.';
else revise = true;
j.revise = revise;
if (revise) {
  j.revisionRound = (j.revisionRound || 0) + 1;
  j.revisionNotes = ['HUMAN FEEDBACK (revision ' + j.revisionRound + '): ' + text];
  j.useFallback = false;
  j.needAutoFix = false;
}
j.cancelMessage = 'Job ' + j.jobId + ' ("' + ((j.storyboard && j.storyboard.title) || j.spec.title) + '") was not saved to Drive. ' + reason;
const dir = j.jobDir;
j.cleanupCmd = (!revise && j.cfg.cleanupAfter && /\/video-jobs\/job_[a-z0-9]+$/.test(dir)) ? 'rm -rf "' + dir + '"' : 'echo "cleanup skipped"';
return [{ json: j }];
